	Val  int
	Next *ListNode
	Prev *ListNode
}

func RemoveDuplicates(head *ListNode) *ListNode {
	current := head

	for current != nil {
		nextDifferent := current.Next

		for nextDifferent != nil && nextDifferent.Val == current.Val {
			nextDifferent = nextDifferent.Next
		}

		current.Next = nextDifferent
		if nextDifferent != nil {
			nextDifferent.Prev = current
		}

		current = nextDifferent
	}

	return head
}
```

For `3 <-> 3 <-> 3 <-> 5`, the inner loop moves to `5`, then the first `3` is connected directly to it.

